-- The audit trail of run 20260916T111405Z: the evaluation run behind
-- test_results.csv and docs/reflection-report.md. Dumped from the run's
-- munder_difflin.db, which .gitignore keeps out of the repo because
-- init_database rewrites it. transactions carries its rowid explicitly:
-- transaction_links joins on it, so it has to survive the round trip.
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS agent_steps (
      step_id        TEXT PRIMARY KEY,
      parent_step_id TEXT,
      run_id         TEXT NOT NULL,
      request_id     TEXT NOT NULL,
      seq            INTEGER NOT NULL,
      agent          TEXT NOT NULL,
      kind           TEXT NOT NULL,
      name           TEXT NOT NULL,
      inputs         TEXT,
      outputs        TEXT,
      started_at     TEXT NOT NULL,
      finished_at    TEXT,
      error          TEXT
    );
CREATE TABLE IF NOT EXISTS blocker_signals (
      step_id  TEXT NOT NULL,
      line_id  TEXT NOT NULL,
      code     TEXT NOT NULL,
      detail   TEXT
    );
CREATE TABLE IF NOT EXISTS transaction_links (
      transaction_rowid INTEGER NOT NULL,
      run_id            TEXT NOT NULL,
      request_id        TEXT NOT NULL,
      step_id           TEXT NOT NULL
    );
CREATE TABLE IF NOT EXISTS suspended_flows (
      resume_token TEXT PRIMARY KEY,
      run_id       TEXT NOT NULL,
      request_id   TEXT NOT NULL,
      suspended_at TEXT NOT NULL,
      payload      TEXT NOT NULL
    );
CREATE TABLE IF NOT EXISTS quote_registry (
      quote_line_id  TEXT PRIMARY KEY,
      run_id         TEXT NOT NULL,
      request_id     TEXT NOT NULL,
      line_id        TEXT NOT NULL,
      item_name      TEXT NOT NULL,
      units          INTEGER NOT NULL,
      unit_price     REAL NOT NULL,
      band           TEXT NOT NULL,
      discount_rate  REAL NOT NULL,
      line_total     REAL NOT NULL,
      quoted_at      TEXT NOT NULL
    );
CREATE TABLE IF NOT EXISTS quote_fulfilments (
      transaction_rowid INTEGER NOT NULL,
      quote_line_id     TEXT NOT NULL
    );
CREATE TABLE IF NOT EXISTS request_cash (
      run_id      TEXT NOT NULL,
      request_id  TEXT NOT NULL,
      cash_before REAL NOT NULL,
      cash_after  REAL NOT NULL,
      cash_delta  REAL NOT NULL,
      measured_at TEXT NOT NULL,
      PRIMARY KEY (run_id, request_id)
    );
CREATE TABLE IF NOT EXISTS transactions (
	id FLOAT, 
	item_name FLOAT, 
	transaction_type FLOAT, 
	units FLOAT, 
	price FLOAT, 
	transaction_date FLOAT
);
COMMIT;
